"""Provided finite RESP2 reader for an explicit private exercise Unix socket."""
import socket

class RedisError(Exception):pass

class Client:
    def __init__(self,path):
        self.socket=socket.socket(socket.AF_UNIX,socket.SOCK_STREAM);self.socket.settimeout(3)
        try:self.socket.connect(str(path));self.stream=self.socket.makefile('rb')
        except BaseException:self.socket.close();raise
    def command(self,*parts):
        operation=parts[0].decode('ascii')if parts and isinstance(parts[0],bytes)else str(parts[0])if parts else''
        if operation.upper()not in {'HGETALL','HGET','HKEYS','HMGET','LRANGE','TYPE','EXISTS','GET','INFO'}:raise ValueError('provided client only supports read commands')
        values=[part if isinstance(part,bytes)else str(part).encode('utf-8')for part in parts]
        self.socket.sendall(b'*'+str(len(values)).encode()+b'\r\n'+b''.join(b'$'+str(len(value)).encode()+b'\r\n'+value+b'\r\n'for value in values));return self.read()
    def read(self):
        line=self.stream.readline()
        if not line or not line.endswith(b'\r\n'):raise ConnectionError('invalid RESP line')
        tag,value=line[:1],line[1:-2]
        if tag==b'+':return value.decode('utf-8')
        if tag==b'-':raise RedisError(value.decode('utf-8'))
        if tag==b':':return int(value)
        if tag==b'$':
            count=int(value)
            if count<0:return None
            data=self.stream.read(count)
            if len(data)!=count or self.stream.read(2)!=b'\r\n':raise ConnectionError('truncated RESP bulk')
            return data.decode('utf-8')
        if tag==b'*':
            count=int(value);return None if count<0 else[self.read()for _ in range(count)]
        raise ValueError('unsupported RESP tag')
    def close(self):
        try:self.stream.close()
        finally:self.socket.close()

