    for window,start in [('before',1000),('after',2000)]:
        key=policy['prefix']+':window:'+window;meta={'id':window,'start_ms':start,'end_ms':start+100,'closed':1,'unlinked_requests':0,'policy_sha256':policy_hash};command('HSET',key,*[part for pair in meta.items()for part in pair]);keys.append(key)
        for business in policy['businesses']:
            name=business['id'];rows=traces(window,name,good);stats={**totals(rows),'window_id':window,'business_id':name};key=policy['prefix']+':stats:'+window+':'+name;command('HSET',key,*[part for pair in stats.items()for part in pair]);keys.append(key)
            key=policy['prefix']+':events:'+window+':'+name;command('RPUSH',key,*[json.dumps(row,sort_keys=True)for row in rows]);keys.append(key)
    return keys
